    B2F.robe(ctx, h, coat[0], coat[1], 6.2, 8.2); ctx.fillStyle = 'rgba(0,0,0,.2)'; ctx.fillRect(-.6, -5, 1.2, 17); // the felt coat, closed to the ground
    [['#8a2a1e', 0], ['#c8a050', 1.1], ['#2a3a5a', 2.2]].forEach(([c, d]) => { ctx.fillStyle = c; ctx.fillRect(-8 + d*.1, 8.6 + d, 16 - d*.2, .9); }); ctx.fillStyle = 'rgba(255,236,200,.35)'; for (let i=0;i<8;i++) ctx.fillRect(-7.4 + i*1.9, 9.6, .6, .6); // a woven band at the hem
    ctx.fillStyle = '#8a2a1e'; ctx.fillRect(-6, 1.4, 12, 1.6); ctx.fillStyle = '#c8a050'; ctx.fillRect(-6, 1.9, 12, .4); poly(ctx, [[-3,3],[-1.6,3],[-1.2,8],[-2.8,8.4]], '#8a2a1e'); // a sash, its end hanging
    ell(ctx, 4.4, 4.6, 1.5, 1.9, '#4a3420'); ctx.fillStyle = '#2a1c10'; ctx.fillRect(3.8, 2.8, 1.2, .6); // a pouch: the coin will go in it, or the knives
