    h.head(sk, 4.2, -11.4); ctx.strokeStyle = 'rgba(50,30,20,.45)'; ctx.lineWidth = .4; ctx.beginPath(); ctx.moveTo(-2.6, -10.4); ctx.lineTo(-1.6, -9.8); ctx.moveTo(3.6, -12.8); ctx.lineTo(4.2, -11.8); ctx.moveTo(-1.6, -14); ctx.lineTo(2.6, -14.2); ctx.moveTo(-1.2, -13.4); ctx.lineTo(2.2, -13.5); ctx.stroke(); // lines, and lines
    ctx.fillStyle = '#e8e4d8'; ctx.fillRect(-1.4, -12.6, 2, .6); ctx.fillRect(1.8, -12.6, 2, .6); ctx.fillStyle = 'rgba(24,14,10,.85)'; ctx.fillRect(-.6, -11.6, 1.1, .7); ctx.fillRect(2.4, -11.6, 1.1, .7); // white brows, eyes half-lidded, looking down
    poly(ctx, [[-3.2,-9.6],[4.4,-9.6],[4,-6],[2.4,-1.4],[.6,1],[-1.4,-1.6],[-3,-5.6]], '#dcd8cc'); ctx.strokeStyle = 'rgba(150,140,124,.6)'; ctx.lineWidth = .4; ctx.beginPath(); for (let i=0;i<3;i++){ ctx.moveTo(-1.6 + i*1.6, -8.6); ctx.lineTo(-.6 + i*1.2, -1.6 + i*.4); } ctx.stroke(); ctx.fillStyle = 'rgba(255,255,255,.25)'; ctx.fillRect(-2.4, -9.2, 1.2, 5); // a long white beard
