    h.head(sk, 4.3, -11.2); ctx.fillStyle = '#e8e2d4'; [[-1.6,-13.2],[-.4,-13.6],[.8,-13.2],[2,-13.4],[3.2,-13.6],[4.2,-13],[-1.6,-10],[4.4,-10.2],[1.4,-9.6]].forEach(([x, y]) => ctx.fillRect(x, y, .6, .6)); h.look('rgba(20,12,8,.9)', -11.8); // white clay in dots round the eyes
